import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { resumeApi } from '../services/api';

export default function Dashboard() {
  const { user } = useAuth();
  const [resumes, setResumes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState('');

  useEffect(() => {
    resumeApi.getAll()
      .then((res) => setResumes(res.data))
      .catch(() => setErrorMsg('Could not load your resumes.'))
      .finally(() => setLoading(false));
  }, []);

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this resume?')) return;
    await resumeApi.remove(id);
    setResumes(resumes.filter((r) => r.id !== id));
  };

  const isRecruiterLike = ['RECRUITER', 'HIRING_MANAGER', 'ADMIN'].includes(user.role);

  return (
    <div className="page-container">
      <div className="page-header">
        <h1>Welcome, {user.fullName.split(' ')[0]}</h1>
        {!isRecruiterLike && (
          <Link to="/resume/new" className="btn-primary">+ New Resume</Link>
        )}
      </div>

      {isRecruiterLike && (
        <div className="callout">
          You're signed in as a {user.role.replace('_', ' ').toLowerCase()}. Head to{' '}
          <Link to="/recruiter">Candidate Search</Link> to browse and search resumes shared by job seekers.
        </div>
      )}

      {!isRecruiterLike && (
        <>
          {loading && <p>Loading your resumes…</p>}
          {errorMsg && <div className="error-banner">{errorMsg}</div>}
          {!loading && resumes.length === 0 && (
            <p>You haven't created any resumes yet. Click "New Resume" to get started.</p>
          )}
          <div className="resume-grid">
            {resumes.map((r) => (
              <div className="resume-card" key={r.id}>
                <h3>{r.title}</h3>
                <p className="muted">{r.headline || 'No headline yet'}</p>
                <span className={`status-badge status-${r.status.toLowerCase()}`}>{r.status}</span>
                <div className="card-actions">
                  <Link to={`/resume/${r.id}`}>Edit</Link>
                  {/* Front-end only demo: no backend file generation yet, so this is a placeholder
                      that intentionally performs no action. Wire this up once a real
                      "download PDF" endpoint exists. */}
                  <button
                    type="button"
                    className="btn-link"
                    onClick={(e) => e.preventDefault()}
                    title="Coming soon"
                  >
                    Download Resume
                  </button>
                  <button className="btn-link danger" onClick={() => handleDelete(r.id)}>Delete</button>
                </div>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}
